//go:build amd64

package floats

// The AVX2+FMA kernel of the squared magnitude (sqmag.go), generated by go-asmgen
// (sqmag_amd64_gen.go) into sqmag_amd64.s: four bins per step, for a CPU with the
// AVX2+FMA of the other kernels (hasAVX2FMA, kernels_amd64.go); the portable loop
// otherwise. The Go code finishes the last bins. No kernel keeps a pointer:
// go:noescape.
//
//go:noescape
func sqmagAVX2(dst, c []float64, s float64)

func squaredMagnitude(dst, c []float64, s float64) {
	if !hasAVX2FMA {
		sqmagTail(dst, c, s, 0)
		return
	}
	sqmagAVX2(dst, c, s)
	sqmagTail(dst, c, s, len(dst)&^3)
}
